                return False
            if not self._live(entry, now):
                del self.entries[key]
                self._persist()
                return False
            previous = self.entries.pop(key)
            try:
                self._persist()
            except StoreError:
                self.entries[key] = previous
                raise
            return True

    def keys(self) -> list[str]:
