        length_text = self.headers.get("Content-Length")
        if length_text is None:
            return None, (HTTPStatus.LENGTH_REQUIRED, "Content-Length is required")
        try:
            length = int(length_text)
        except ValueError:
            return None, (HTTPStatus.BAD_REQUEST, "invalid Content-Length")
        if length < 0:
            return None, (HTTPStatus.BAD_REQUEST, "invalid Content-Length")
        if length > MAX_BODY:
            self.close_connection = True
            return None, (HTTPStatus.REQUEST_ENTITY_TOO_LARGE, "request body exceeds 1 MiB")
        raw = self.rfile.read(length)
        try:
            body = json.loads(raw, parse_constant=Store._bad_constant)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
            return None, (HTTPStatus.BAD_REQUEST, "malformed JSON")
        if not isinstance(body, dict):
            return None, (HTTPStatus.BAD_REQUEST, "request body must be a JSON object")
        return body, None

    def _store_error(self, exc: StoreError) -> None:
        print(str(exc), file=sys.stderr)
        self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "storage operation failed")

    def do_GET(self) -> None:
        parsed = urlsplit(self.path)
        if not parsed.query and parsed.path == "/health":
            self._json(HTTPStatus.OK, {"status": "ok"})
            return
        if not parsed.query and parsed.path == "/v1/keys":
            try:
                self._json(HTTPStatus.OK, {"keys": self.server.store.keys()})
            except StoreError as exc:
                self._store_error(exc)
            return
        key, error = self._key()
        if key is None:
            self._error(HTTPStatus.NOT_FOUND, error or "unknown route")
            return
        try:
            found, value = self.server.store.get(key)
        except StoreError as exc:
            self._store_error(exc)
            return
        if not found:
            self._error(HTTPStatus.NOT_FOUND, "key not found")
            return
        self._json(HTTPStatus.OK, {"key": key, "value": value})

    def do_PUT(self) -> None:
        key, error = self._key()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST if error != "unknown route" else HTTPStatus.NOT_FOUND, error or "invalid key")
            return
        body, body_error = self._body()
        if body_error is not None:
            self._error(*body_error)
            return
        assert body is not None
        if "value" not in body or not set(body).issubset({"value", "ttl_seconds"}):
            self._error(HTTPStatus.BAD_REQUEST, "body requires value and may only include ttl_seconds")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (
            isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0
        ):
            self._error(HTTPStatus.BAD_REQUEST, "ttl_seconds must be finite and greater than zero")
            return
        try:
            created = self.server.store.put(key, body["value"], ttl)
        except StoreError as exc:
            self._store_error(exc)
            return
        self._json(HTTPStatus.CREATED if created else HTTPStatus.OK, {"key": key, "value": body["value"]})

    def do_DELETE(self) -> None:
        key, error = self._key()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST if error != "unknown route" else HTTPStatus.NOT_FOUND, error or "invalid key")
            return
        try:
            deleted = self.server.store.delete(key)
        except StoreError as exc:
            self._store_error(exc)
            return
        if not deleted:
            self._error(HTTPStatus.NOT_FOUND, "key not found")
            return
        self.send_response(HTTPStatus.NO_CONTENT)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _unsupported(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    do_POST = _unsupported
    do_PATCH = _unsupported
    do_HEAD = _unsupported
    do_OPTIONS = _unsupported


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = Server((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(_signum: int, _frame: object) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
import http.client
import json
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path


ROOT = Path(__file__).parent


class RunningServer:
    def __init__(self, data: Path):
        self.process = subprocess.Popen(
            [sys.executable, str(ROOT / "server.py"), "--host", "127.0.0.1", "--port", "0", "--data", str(data)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        line = self.process.stdout.readline().strip()
        if not line.startswith("LISTENING "):
            raise RuntimeError(f"server failed: {line} {self.process.stderr.read()}")
        self.port = int(line.split()[1])

    def request(self, method, path, body=None, headers=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        encoded = None if body is None else json.dumps(body).encode()
        request_headers = {} if headers is None else dict(headers)
        if encoded is not None:
            request_headers["Content-Type"] = "application/json"
        connection.request(method, path, encoded, request_headers)
        response = connection.getresponse()
        raw = response.read()
        result = response.status, response.getheader("Content-Type"), raw
        connection.close()
        return result

    def close(self):
        self.process.terminate()
        self.process.wait(timeout=3)


class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.data = Path(self.temp.name) / "nested" / "data.json"
        self.server = RunningServer(self.data)

    def tearDown(self):
        self.server.close()
        self.temp.cleanup()

    def test_crud_sorting_encoding_and_restart(self):
        status, content_type, raw = self.server.request("GET", "/health")
        self.assertEqual((status, content_type, json.loads(raw)), (200, "application/json", {"status": "ok"}))
        self.assertEqual(self.server.request("PUT", "/v1/kv/z", {"value": [1, None]})[0], 201)
        self.assertEqual(self.server.request("PUT", "/v1/kv/a%20b", {"value": "first"})[0], 201)
        self.assertEqual(self.server.request("PUT", "/v1/kv/a%20b", {"value": "second"})[0], 200)
        self.assertEqual(json.loads(self.server.request("GET", "/v1/kv/a%20b")[2]), {"key": "a b", "value": "second"})
        self.assertEqual(json.loads(self.server.request("GET", "/v1/keys")[2]), {"keys": ["a b", "z"]})
        self.server.close()
        self.server = RunningServer(self.data)
        self.assertEqual(json.loads(self.server.request("GET", "/v1/kv/z")[2])["value"], [1, None])
        self.assertEqual(self.server.request("DELETE", "/v1/kv/z")[0], 204)
        self.assertEqual(self.server.request("DELETE", "/v1/kv/z")[0], 404)

    def test_ttl_and_validation(self):
        self.assertEqual(self.server.request("PUT", "/v1/kv/short", {"value": 1, "ttl_seconds": 0.08})[0], 201)
        time.sleep(0.12)
        self.assertEqual(self.server.request("GET", "/v1/kv/short")[0], 404)
        for ttl in (0, -1, True, float("inf")):
            self.assertEqual(self.server.request("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": ttl})[0], 400)
        self.assertEqual(self.server.request("PUT", "/v1/kv/a%2Fb", {"value": 1})[0], 400)
        self.assertEqual(self.server.request("PUT", "/v1/kv/x", [1])[0], 400)
        self.assertEqual(self.server.request("POST", "/health", {})[0], 405)
        self.assertEqual(self.server.request("GET", "/missing")[0], 404)


